import { z } from "zod";

/** HTML checkbox: present ("on") when checked, absent when unchecked. */
export const checkbox = z.preprocess((v) => v === "on" || v === "true" || v === true, z.boolean());

const phone = z
  .string()
  .trim()
  .transform((v) => v.replace(/[\s-]/g, ""))
  .pipe(z.string().regex(/^(\+91)?[6-9]\d{9}$/, "Enter a valid 10-digit Indian mobile number"));

export const registerSchema = z.object({
  name: z.string().trim().min(2, "Name is too short").max(80),
  email: z.email("Enter a valid email").trim().toLowerCase().max(160),
  phone,
  password: z
    .string()
    .min(8, "Use at least 8 characters")
    .max(128)
    .regex(/[A-Za-z]/, "Include a letter")
    .regex(/\d/, "Include a number"),
});

export const loginSchema = z.object({
  email: z.email("Enter a valid email").trim().toLowerCase(),
  password: z.string().min(1, "Enter your password").max(128),
});

export const addressSchema = z.object({
  name: z.string().trim().min(2).max(80),
  phone,
  line1: z.string().trim().min(3, "Enter house / street").max(160),
  line2: z.string().trim().max(160).optional().default(""),
  city: z.string().trim().min(2).max(80),
  state: z.string().trim().min(2).max(80),
  pincode: z.string().trim().regex(/^[1-9]\d{5}$/, "Enter a valid 6-digit PIN code"),
});

export const checkoutSchema = z.object({
  email: z.email().trim().toLowerCase(),
  address: addressSchema,
  couponCode: z.string().trim().max(40).optional().nullable(),
  preferEmi: z.boolean().default(false),
  notes: z.string().trim().max(500).optional(),
});

export const leadSchema = z.object({
  type: z.enum(["B2B_QUOTE", "ENGRAVING", "CONTACT"]),
  name: z.string().trim().min(2).max(80),
  company: z.string().trim().max(120).optional(),
  email: z.union([z.email().trim().toLowerCase(), z.literal("")]).optional(),
  phone,
  city: z.string().trim().max(80).optional(),
  message: z.string().trim().max(2000).optional(),
  details: z.record(z.string(), z.string().max(500)).default({}),
  // Honeypot — real users never fill this hidden field.
  website: z.string().max(0).optional(),
});

export const productSchema = z.object({
  name: z.string().trim().min(2).max(160),
  slug: z.string().trim().max(100).optional(),
  sku: z.string().trim().min(2).max(60),
  brand: z.string().trim().max(80).optional(),
  material: z.string().trim().max(60).optional(),
  categoryId: z.string().min(1, "Choose a category"),
  shortDescription: z.string().trim().max(300).optional(),
  description: z.string().trim().max(20000).default(""),
  price: z.coerce.number().positive("Price must be greater than 0").max(10_000_000),
  mrp: z.coerce.number().positive().max(10_000_000),
  costPrice: z.coerce.number().min(0).max(10_000_000).optional(),
  gstRate: z.coerce.number().int().refine((v) => [0, 3, 5, 12, 18, 28].includes(v), "GST must be 0, 3, 5, 12, 18 or 28"),
  hsnCode: z.string().trim().max(12).optional(),
  stock: z.coerce.number().int().min(0).max(1_000_000),
  lowStockThreshold: z.coerce.number().int().min(0).max(10_000).default(5),
  weightGrams: z.coerce.number().int().min(0).max(1_000_000).optional(),
  warranty: z.string().trim().max(120).optional(),
  tags: z.string().trim().max(500).optional(),
  specs: z.string().max(5000).optional(),
  isActive: checkbox,
  isFeatured: checkbox,
  emiEligible: checkbox,
  engravingAvailable: checkbox,
});
